import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import io
import base64
import re
from collections import Counter
import numpy as np

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# ── Basic counts ───────────────────────────────────────────────────────────────
total_questions = len(df)
years = sorted(df['year'].unique())
year_count = len(years)
type_counts = df['type'].value_counts()
type_pct = (type_counts / total_questions * 100).round(1)

# Per-year breakdown
year_type = df.groupby(['year', 'type']).size().unstack(fill_value=0)
year_totals = df.groupby('year').size()

# Ensure all three types exist as columns
for t in ['MCQs', 'Short', 'Long']:
    if t not in year_type.columns:
        year_type[t] = 0
year_type = year_type[['MCQs', 'Short', 'Long']]

# KPIs
avg_per_type = {t: round(year_type[t].mean(), 1) for t in ['MCQs', 'Short', 'Long']}
avg_total = round(year_totals.mean(), 1)

# Year-over-year change
yoy = pd.DataFrame({
    'Total': year_totals,
    'Change': year_totals.diff(),
    'Pct_Change': (year_totals.pct_change() * 100).round(1)
})
yoy = yoy.fillna('-')

# Type ratios per year
type_ratio = (year_type.div(year_type.sum(axis=1), axis=0) * 100).round(1)

# ── Keyword / topic analysis ──────────────────────────────────────────────────
stop_words = {
    'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'from', 'as',
    'this', 'that', 'these', 'those', 'it', 'its', 'or', 'and', 'not',
    'but', 'if', 'then', 'than', 'so', 'no', 'do', 'does', 'did', 'will',
    'would', 'shall', 'should', 'may', 'might', 'must', 'can', 'could',
    'what', 'which', 'who', 'whom', 'how', 'when', 'where', 'why', 'all',
    'each', 'every', 'any', 'some', 'such', 'other', 'into', 'also',
    'has', 'have', 'had', 'having', 'their', 'them', 'they', 'we', 'you',
    'he', 'she', 'his', 'her', 'our', 'your', 'my', 'me', 'us', 'him',
    'about', 'up', 'out', 'more', 'most', 'between', 'among', 'through',
    'during', 'before', 'after', 'above', 'below', 'same', 'different',
    'following', 'given', 'used', 'use', 'called', 'write', 'define',
    'explain', 'give', 'list', 'name', 'following', 'example', 'following',
    'write', 'program', 'statement', 'statements', 'two', 'three', 'four',
    'one', 'number', 'numbers', 'value', 'values', 'following', 'ii', 'iii',
    'iv', 'vi', 'vii', 'viii', 'ix', 'x', 'xi', 'xii', 'xiii', 'xiv', 'xv',
    'xvi', 'xvii', 'xviii', 'xix', 'i', 'v', 'following', 'print', 'printf',
    'scanf', 'void', 'int', 'main', 'return', 'input', 'output', 'find',
    'check', 'calculate', 'display', 'show', 'enter', 'read', 'prints',
    'equivalent', 'full', 'form', 'difference', 'differentiate', 'purpose',
    'advantages', 'various', 'types', 'type', 'mean', 'meant', 'role',
    'function', 'functions', 'language', 'data', 'database', 'dbms',
    'ms', 'access', 'c', 'program', 'programs', 'expression', 'expressions',
    'following', 'code', 'format', 'specifiers', 'specifier', 'correctly',
    'rewrite', 'determine', 'identify', 'debug', 'convert', 'steps', 'create',
    'another', 'well', 'let', 'hint', 'using', 'without', 'case', 'cases',
    'definition', 'describe', 'discuss', 'declare', 'structure', 'structures',
    'getch', 'include', 'stdio', 'clrscr', 'also', 'part', 'parts', 'make',
    'made', 'represents', 'represented', 'refer', 'refers', 'known', 'sometimes',
    'however', 'whether', 'within', 'performs', 'performed', 'consider',
    'considered', 'call', 'called', 'invokes', 'invoke', 'itself', 'only',
    'just', 'need', 'needed', 'requires', 'required', 'require', 'necessary',
    'must', 'begin', 'begins', 'start', 'starts', 'end', 'ends', 'perform',
    'computes', 'compute', 'represents', 'ensure', 'ensures', 'maintain',
    'maintains', 'stand', 'stands', 'where', 'whose', 'which', 'like'
}

def extract_keywords(text):
    text = str(text).lower()
    text = re.sub(r'[^a-z\s]', ' ', text)
    words = text.split()
    return [w for w in words if len(w) > 2 and w not in stop_words]

all_keywords = []
type_keywords = {'MCQs': [], 'Short': [], 'Long': []}
year_keywords = {y: [] for y in years}

for _, row in df.iterrows():
    kws = extract_keywords(row['question'])
    all_keywords.extend(kws)
    type_keywords[row['type']].extend(kws)
    year_keywords[row['year']].extend(kws)

overall_freq = Counter(all_keywords).most_common(30)
mcq_freq = Counter(type_keywords['MCQs']).most_common(15)
short_freq = Counter(type_keywords['Short']).most_common(15)
long_freq = Counter(type_keywords['Long']).most_common(15)

# Topic categories
topic_map = {
    'C Programming Fundamentals': ['variable', 'constant', 'identifier', 'operator',
        'operators', 'data', 'types', 'reserved', 'words', 'syntax', 'comment',
        'comments', 'preprocessor', 'directive', 'header', 'file', 'expression',
        'precedence', 'assignment', 'increment', 'decrement', 'unary', 'binary',
        'ternary', 'bitwise', 'relational', 'logical', 'arithmetic', 'sizeof',
        'casting', 'scope', 'storage', 'classes', 'pointer', 'pointers'],
    'Control Structures': ['loop', 'loops', 'for', 'while', 'do', 'while', 'nested',
        'break', 'continue', 'switch', 'if', 'else', 'goto', 'control',
        'selection', 'iteration', 'conditional', 'decision', 'ladder'],
    'Functions & Recursion': ['function', 'functions', 'recursive', 'recursion',
        'prototype', 'parameters', 'arguments', 'call', 'return', 'library',
        'user', 'defined', 'actual', 'formal', 'parameter'],
    'Input/Output & Formatting': ['printf', 'scanf', 'input', 'output', 'format',
        'specifier', 'specifiers', 'escape', 'sequence', 'gets', 'puts',
        'getchar', 'putchar', 'getch', 'getche', 'clrscr', 'formatted',
        'unformatted', 'precision', 'field', 'width'],
    'Arrays & Strings': ['array', 'arrays', 'string', 'strings', 'character',
        'characters', 'strlen', 'index', 'element'],
    'Data Files & File Handling': ['file', 'files', 'data', 'fopen', 'fclose',
        'fscanf', 'fprintf', 'fgets', 'fputs', 'mode', 'modes', 'opening',
        'handling', 'operations', 'record', 'records'],
    'Structures & Unions': ['structure', 'structures', 'union', 'struct',
        'member', 'members'],
    'Database Concepts': ['database', 'dbms', 'rdbms', 'relational', 'hierarchical',
        'network', 'model', 'models', 'table', 'tables', 'tuple', 'attribute',
        'entity', 'entities', 'field', 'fields', 'record', 'primary', 'key',
        'foreign', 'candidate', 'composite', 'super', 'alternate', 'normalization',
        'normal', 'form', 'schema', 'integrity', 'relationship', 'relationships',
        'one', 'many', 'redundancy', 'ddl', 'dml', 'dcl', 'tcl', 'sql',
        'query', 'queries', 'dba', 'administrator', 'dictionary', 'view',
        'index', 'acid', 'er', 'diagram', 'referential', 'object', 'objects'],
    'MS Access': ['access', 'report', 'form', 'query', 'macro', 'module',
        'object', 'objects', 'tools', 'properties', 'vba', 'currency',
        'autonumber', 'auto', 'number', 'text', 'date']
}

def categorize_keywords(freq_list):
    cat_counts = {}
    for cat, keywords in topic_map.items():
        count = sum(c for kw, c in freq_list if kw in keywords)
        if count > 0:
            cat_counts[cat] = count
    return cat_counts

topic_overall = categorize_keywords(all_keywords)
topic_overall_sorted = dict(sorted(topic_overall.items(), key=lambda x: -x[1]))

# ── Chart generation ───────────────────────────────────────────────────────────
plt.style.use('seaborn-v0_8-whitegrid')
PRIMARY = '#1a5276'
SECONDARY = '#2e86c1'
ACCENT = '#e74c3c'
COLORS = {'MCQs': '#2e86c1', 'Short': '#27ae60', 'Long': '#e67e22'}
YEAR_COLOR = '#1a5276'

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

# Chart 1: Total questions per year (line + bar)
fig1, ax1 = plt.subplots(figsize=(10, 5))
bars = ax1.bar(years, year_totals.values, color=SECONDARY, alpha=0.7, width=0.6, zorder=2)
ax1.plot(years, year_totals.values, color=ACCENT, marker='o', linewidth=2.5, markersize=8, zorder=3)
for i, (y, v) in enumerate(zip(years, year_totals.values)):
    ax1.text(y, v + 0.8, str(v), ha='center', va='bottom', fontweight='bold', fontsize=10)
ax1.set_xlabel('Year', fontsize=12)
ax1.set_ylabel('Total Questions', fontsize=12)
ax1.set_title('Total Examination Questions by Year (2015–2025)', fontsize=14, fontweight='bold')
ax1.set_xticks(years)
ax1.set_ylim(0, max(year_totals.values) + 6)
ax1.grid(axis='y', alpha=0.3)
fig1.tight_layout()
chart1_b64 = fig_to_base64(fig1)

# Chart 2: Stacked bar - question types per year
fig2, ax2 = plt.subplots(figsize=(10, 6))
bottom = np.zeros(len(years))
for t in ['MCQs', 'Short', 'Long']:
    vals = year_type[t].values
    ax2.bar(years, vals, bottom=bottom, label=t, color=COLORS[t], width=0.6, alpha=0.85)
    for i, v in enumerate(vals):
        if v > 0:
            ax2.text(years[i], bottom[i] + v/2, str(v), ha='center', va='center',
                     fontweight='bold', fontsize=9, color='white')
    bottom += vals
ax2.set_xlabel('Year', fontsize=12)
ax2.set_ylabel('Number of Questions', fontsize=12)
ax2.set_title('Question Type Distribution by Year', fontsize=14, fontweight='bold')
ax2.set_xticks(years)
ax2.legend(fontsize=11, loc='upper left')
ax2.grid(axis='y', alpha=0.3)
fig2.tight_layout()
chart2_b64 = fig_to_base64(fig2)

# Chart 3: Line chart - type trends
fig3, ax3 = plt.subplots(figsize=(10, 5.5))
for t in ['MCQs', 'Short', 'Long']:
    ax3.plot(years, year_type[t].values, marker='o', linewidth=2.5, markersize=7,
             label=t, color=COLORS[t])
    for i, v in enumerate(year_type[t].values):
        ax3.text(years[i], v + 0.4, str(v), ha='center', va='bottom', fontsize=9, color=COLORS[t])
ax3.set_xlabel('Year', fontsize=12)
ax3.set_ylabel('Number of Questions', fontsize=12)
ax3.set_title('Question Type Trends Across Years', fontsize=14, fontweight='bold')
ax3.set_xticks(years)
ax3.legend(fontsize=11)
ax3.grid(alpha=0.3)
fig3.tight_layout()
chart3_b64 = fig_to_base64(fig3)

# Chart 4: Pie chart - overall type distribution
fig4, ax4 = plt.subplots(figsize=(7, 7))
wedges, texts, autotexts = ax4.pie(
    type_counts.values, labels=type_counts.index, autopct='%1.1f%%',
    colors=[COLORS[t] for t in type_counts.index],
    startangle=140, textprops={'fontsize': 13, 'fontweight': 'bold'},
    pctdistance=0.75, wedgeprops=dict(width=0.55, edgecolor='white', linewidth=2)
)
for at in autotexts:
    at.set_fontsize(12)
    at.set_color('white')
    at.set_fontweight('bold')
ax4.set_title('Overall Question Type Distribution', fontsize=14, fontweight='bold', pad=20)
fig4.tight_layout()
chart4_b64 = fig_to_base64(fig4)

# Chart 5: Topic frequency bar
fig5, ax5 = plt.subplots(figsize=(11, 6))
topics = list(topic_overall_sorted.keys())
counts = list(topic_overall_sorted.values())
colors5 = plt.cm.viridis(np.linspace(0.2, 0.85, len(topics)))
bars5 = ax5.barh(range(len(topics)), counts, color=colors5, edgecolor='white', height=0.65)
ax5.set_yticks(range(len(topics)))
ax5.set_yticklabels(topics, fontsize=11)
ax5.invert_yaxis()
ax5.set_xlabel('Keyword Frequency', fontsize=12)
ax5.set_title('Recurring Topic Categories (Keyword Frequency)', fontsize=14, fontweight='bold')
for i, v in enumerate(counts):
    ax5.text(v + 1, i, str(v), va='center', fontsize=10, fontweight='bold')
ax5.grid(axis='x', alpha=0.3)
fig5.tight_layout()
chart5_b64 = fig_to_base64(fig5)

# Chart 6: Year-over-year % change
fig6, ax6 = plt.subplots(figsize=(10, 5))
pct_changes = []
for i in range(len(years)):
    if i == 0:
        pct_changes.append(0)
    else:
        prev = year_totals.values[i-1]
        curr = year_totals.values[i]
        pct_changes.append(round((curr - prev) / prev * 100, 1))

colors6 = [ACCENT if v < 0 else SECONDARY for v in pct_changes]
ax6.bar(years, pct_changes, color=colors6, alpha=0.8, width=0.6)
ax6.axhline(y=0, color='black', linewidth=0.8)
for i, v in enumerate(pct_changes):
    if i == 0:
        label = 'N/A'
    else:
        label = f'{v:+.1f}%'
    ax6.text(years[i], v + (1.5 if v >= 0 else -2.5), label, ha='center', fontsize=9, fontweight='bold')
ax6.set_xlabel('Year', fontsize=12)
ax6.set_ylabel('Year-over-Year Change (%)', fontsize=12)
ax6.set_title('Year-over-Year Change in Total Questions', fontsize=14, fontweight='bold')
ax6.set_xticks(years)
ax6.grid(axis='y', alpha=0.3)
fig6.tight_layout()
chart6_b64 = fig_to_base64(fig6)

# Chart 7: Type ratio stacked area
fig7, ax7 = plt.subplots(figsize=(10, 5.5))
mcq_pct = type_ratio['MCQs'].values
short_pct = type_ratio['Short'].values
long_pct = type_ratio['Long'].values
ax7.stackplot(years, mcq_pct, short_pct, long_pct,
              labels=['MCQs', 'Short', 'Long'],
              colors=[COLORS['MCQs'], COLORS['Short'], COLORS['Long']],
              alpha=0.75)
ax7.set_xlabel('Year', fontsize=12)
ax7.set_ylabel('Percentage of Questions (%)', fontsize=12)
ax7.set_title('Question Type Composition Over Time', fontsize=14, fontweight='bold')
ax7.set_xticks(years)
ax7.set_ylim(0, 100)
ax7.legend(loc='upper right', fontsize=11)
ax7.grid(alpha=0.3)
fig7.tight_layout()
chart7_b64 = fig_to_base64(fig7)

# Chart 8: Top 15 keywords overall
fig8, ax8 = plt.subplots(figsize=(10, 6))
top_kw = overall_freq[:15]
kw_labels = [k for k, v in top_kw]
kw_vals = [v for k, v in top_kw]
colors8 = plt.cm.plasma(np.linspace(0.15, 0.8, len(kw_labels)))
ax8.barh(range(len(kw_labels)), kw_vals, color=colors8, edgecolor='white', height=0.65)
ax8.set_yticks(range(len(kw_labels)))
ax8.set_yticklabels(kw_labels, fontsize=11)
ax8.invert_yaxis()
ax8.set_xlabel('Frequency', fontsize=12)
ax8.set_title('Top 15 Recurring Keywords in Questions', fontsize=14, fontweight='bold')
for i, v in enumerate(kw_vals):
    ax8.text(v + 0.5, i, str(v), va='center', fontsize=10, fontweight='bold')
ax8.grid(axis='x', alpha=0.3)
fig8.tight_layout()
chart8_b64 = fig_to_base64(fig8)


# ── Build HTML report ──────────────────────────────────────────────────────────

# Prepare data tables as HTML
def year_dist_rows():
    rows = []
    for y in years:
        mcq = year_type.loc[y, 'MCQs'] if y in year_type.index else 0
        short = year_type.loc[y, 'Short'] if y in year_type.index else 0
        long_ = year_type.loc[y, 'Long'] if y in year_type.index else 0
        total = mcq + short + long_
        rows.append(f'<tr><td>{y}</td><td>{mcq}</td><td>{short}</td><td>{long_}</td><td><strong>{total}</strong></td></tr>')
    return '\n'.join(rows)

def yoy_rows():
    rows = []
    for i, y in enumerate(years):
        total = year_totals[y]
        if i == 0:
            chg = '—'
            pct = '—'
        else:
            prev = year_totals[years[i-1]]
            abs_chg = total - prev
            pct_chg = round(abs_chg / prev * 100, 1)
            chg = f'{abs_chg:+d}'
            pct = f'{pct_chg:+.1f}%'
        rows.append(f'<tr><td>{y}</td><td>{total}</td><td>{chg}</td><td>{pct}</td></tr>')
    return '\n'.join(rows)

def type_ratio_rows():
    rows = []
    for y in years:
        mcq = type_ratio.loc[y, 'MCQs'] if y in type_ratio.index else 0
        short = type_ratio.loc[y, 'Short'] if y in type_ratio.index else 0
        long_ = type_ratio.loc[y, 'Long'] if y in type_ratio.index else 0
        rows.append(f'<tr><td>{y}</td><td>{mcq}%</td><td>{short}%</td><td>{long_}%</td></tr>')
    return '\n'.join(rows)

def keyword_rows(freq_list):
    rows = []
    for kw, c in freq_list:
        rows.append(f'<tr><td>{kw}</td><td>{c}</td></tr>')
    return '\n'.join(rows)

# Year-over-year narrative
def yoy_narrative():
    narratives = []
    for i in range(1, len(years)):
        prev = year_totals[years[i-1]]
        curr = year_totals[years[i]]
        diff = curr - prev
        pct = round(diff / prev * 100, 1)
        if diff > 0:
            narratives.append(f'{years[i]} saw an increase of {diff} questions (+{pct}%) from {prev} to {curr}.')
        elif diff < 0:
