# Prepare data tables as HTML
def year_dist_rows():
    rows = []
    for y in years:
        mcq = year_type.loc[y, 'MCQs'] if y in year_type.index else 0
        short = year_type.loc[y, 'Short'] if y in year_type.index else 0
        long_ = year_type.loc[y, 'Long'] if y in year_type.index else 0
        total = mcq + short + long_
        rows.append(f'<tr><td>{y}</td><td>{mcq}</td><td>{short}</td><td>{long_}</td><td><strong>{total}</strong></td></tr>')
    return '\n'.join(rows)

def yoy_rows():
    rows = []
    for i, y in enumerate(years):
        total = year_totals[y]
        if i == 0:
            chg = '—'
            pct = '—'
        else:
            prev = year_totals[years[i-1]]
            abs_chg = total - prev
            pct_chg = round(abs_chg / prev * 100, 1)
            chg = f'{abs_chg:+d}'
            pct = f'{pct_chg:+.1f}%'
        rows.append(f'<tr><td>{y}</td><td>{total}</td><td>{chg}</td><td>{pct}</td></tr>')
    return '\n'.join(rows)

def type_ratio_rows():
    rows = []
    for y in years:
        mcq = type_ratio.loc[y, 'MCQs'] if y in type_ratio.index else 0
        short = type_ratio.loc[y, 'Short'] if y in type_ratio.index else 0
        long_ = type_ratio.loc[y, 'Long'] if y in type_ratio.index else 0
        rows.append(f'<tr><td>{y}</td><td>{mcq}%</td><td>{short}%</td><td>{long_}%</td></tr>')
    return '\n'.join(rows)

def keyword_rows(freq_list):
    rows = []
    for kw, c in freq_list:
        rows.append(f'<tr><td>{kw}</td><td>{c}</td></tr>')
    return '\n'.join(rows)

# Year-over-year narrative
def yoy_narrative():
    narratives = []
    for i in range(1, len(years)):
        prev = year_totals[years[i-1]]
        curr = year_totals[years[i]]
        diff = curr - prev
        pct = round(diff / prev * 100, 1)
        if diff > 0:
            narratives.append(f'{years[i]} saw an increase of {diff} questions (+{pct}%) from {prev} to {curr}.')
        elif diff < 0:
            narratives.append(f'{years[i]} saw a decrease of {abs(diff)} questions ({pct}%) from {prev} to {curr}.')
        else:
            narratives.append(f'{years[i]} remained unchanged at {curr} questions.')
    return narratives

# Anomaly detection
def detect_anomalies():
    anomalies = []
    mean_total = year_totals.mean()
    std_total = year_totals.std()
    for y in years:
        total = year_totals[y]
        z = (total - mean_total) / std_total if std_total > 0 else 0
        if abs(z) > 1.5:
            direction = 'above' if z > 0 else 'below'
            anomalies.append(f'{y} (total: {total}, {abs(z):.1f}σ {direction} average)')
    # Check for 2020 gap
    if 2020 not in years:
        anomalies.append('Year 2020 is absent from the dataset — likely due to COVID-19 exam cancellations or data unavailability.')
    return anomalies

anomalies = detect_anomalies()
yoy_narr = yoy_narrative()

