    for cat in topic_overall_sorted.keys():
        mcq_c = sum(c for kw, c in type_keywords['MCQs'] if kw in topic_map[cat])
        short_c = sum(c for kw, c in type_keywords['Short'] if kw in topic_map[cat])
        long_c = sum(c for kw, c in type_keywords['Long'] if kw in topic_map[cat])
        total_c = mcq_c + short_c + long_c
        all_rows.append((cat, mcq_c, short_c, long_c, total_c))
    all_rows.sort(key=lambda x: -x[4])
    return all_rows

