from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void_elements = {'br','hr','img','input','meta','link','area','base','col','embed','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'Mismatched tag: </{tag}> (expected </{self.stack[-1] if self.stack else \"?\"}>)')

v = Validator()
with open('/app/output/final_report.html') as f:
    v.feed(f.read())
if v.errors:
    for e in v.errors[:10]:
        print(e)
else:
    print('HTML structure valid')
print(f'Remaining open tags: {v.stack}')
"

